// Generate the frontend's typed colour table from the canonical Go-side JSON artifact.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const frontendRoot = dirname(dirname(fileURLToPath(import.meta.url)))
const sourcePath = join(frontendRoot, '..', 'block', 'vanilla', 'colors.json')
const outputPath = join(frontendRoot, 'src', 'generated', 'blockColors.ts')

const source = JSON.parse(readFileSync(sourcePath, 'utf8'))
const lines = [
  '// Code generated by scripts/generate-block-colors.mjs from block/vanilla/colors.json.',
  '// DO NOT EDIT. Per-face values are retained even though the current mesher uses only `up`.',
  '',
  'export interface GeneratedBlockColor {',
  '  readonly color?: number',
  '  readonly faces?: Readonly<Record<string, number>>',
  '}',
  '',
  'export const GENERATED_BLOCK_COLORS: Readonly<Record<string, GeneratedBlockColor>> = {',
]

function packedColor(value, context) {
  if (typeof value !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(value)) {
    throw new Error(`${context}: expected #RRGGBB, got ${JSON.stringify(value)}`)
  }
  return `0x${value.slice(1).toLowerCase()}`
}

for (const name of Object.keys(source.blocks).sort()) {
  const entry = source.blocks[name]
  if (entry.color !== undefined) {
    lines.push(`  ${JSON.stringify(name)}: { color: ${packedColor(entry.color, name)} },`)
    continue
  }
  if (!entry.faces || typeof entry.faces !== 'object' || !entry.faces.up) {
    throw new Error(`${name}: per-face entries must include an up face`)
  }
  const faces = Object.keys(entry.faces)
    .sort()
    .map((face) => `${JSON.stringify(face)}: ${packedColor(entry.faces[face], `${name}.${face}`)}`)
    .join(', ')
  lines.push(`  ${JSON.stringify(name)}: { faces: { ${faces} } },`)
}

lines.push('}', '')
const generated = `${lines.join('\n')}\n`

if (process.argv.includes('--check')) {
  const current = readFileSync(outputPath, 'utf8')
  if (current !== generated) {
    console.error('src/generated/blockColors.ts is stale; run npm run generate:colors')
    process.exitCode = 1
  }
} else {
  mkdirSync(dirname(outputPath), { recursive: true })
  writeFileSync(outputPath, generated)
  console.log(`generated ${Object.keys(source.blocks).length} block colours`)
}
